import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int MOD = sc.nextInt();
        long[] DP = new long[N];
        DP[0] = 1;
        long[] Cum = new long[N + 1];
        Cum[1] = 1;
        for(int i1 = 1; i1 < N; i1++){
            int i2 = N - i1;
            long Value = Cum[i1];
            for(int j = 2; j <= N; j++){
                if(i2 * j > N) break;
                long startIndex = N - i2 * j + 1;
                long endIndex = Math.max(0, N - i2 * j - j + 1);
                Value += Cum[(int)startIndex] - Cum[(int)Math.max(0, endIndex)];
                Value %= MOD;
            }
            Cum[i1 + 1] += Cum[i1] + Value;
            Cum[i1 + 1] %= MOD;
            DP[i1] = Value;
        }
        System.out.println(DP[N - 1] % MOD);
        sc.close();
    }
}

